import pandas as pd, numpy as np
exec(open('opt.py').read().split('# seed')[0])
best=np.load('best.npy')
rng=np.random.default_rng(1)
def worstscore(x):
    pts=[x]
    for i in range(len(cols)):
        for s in (0.95,0.975,1.025,1.05):
            v=x.copy(); v[i]=np.clip(x[i]*s,lo[i],hi[i]); pts.append(v)
    p=pred(np.array(pts))
    return 0.35*p[0]+0.65*p[1:].min(), p[0], p[1:].min()
cur=best.copy(); cs=worstscore(cur)[0]
for it in range(120):
    scale=0.05 if it<60 else 0.015
    cands=[]
    for _ in range(25):
        step=(hi-lo)*rng.normal(0,scale,len(cols))
        k=rng.integers(1,6)  # perturb few dims
        mask=np.zeros(len(cols),bool); mask[rng.choice(len(cols),k,replace=False)]=True
        c=cur.copy(); c[mask]=np.clip(cur+step,lo,hi)[mask]; cands.append(c)
    for c in cands:
        s=worstscore(c)[0]
        if s>cs: cs=s; cur=c
    if it%20==0: print(it,cs,worstscore(cur))
print(worstscore(cur))
for c,v in zip(cols,cur): print(f'{c}={round(v,4)}')
np.save('best2.npy',cur)
